import { createRoot } from 'react-dom/client';
import './index.css';
/**
 * Sample for Crosshair in chart
 */
import * as React from "react";
import { ChartComponent, SeriesCollectionDirective, SeriesDirective, Inject, LineSeries, DateTime, Legend, Crosshair } from '@syncfusion/ej2-react-charts';
import { Browser } from '@syncfusion/ej2-base';
import { SampleBase } from './sample-base';
export class CrosshairChart extends SampleBase {
    render() {
        return (<div className='control-pane'>
                <div className='control-section'>
                    <ChartComponent id='charts' style={{ textAlign: "center" }} primaryXAxis={{
                interval: 1,
                crosshairTooltip: { enable: true },
                majorGridLines: { width: 0 },
                majorTickLines: { width: 0 },
                lineStyle: { width: 0 },
                title: 'Year'
            }} load={this.load.bind(this)} primaryYAxis={{
                title: "Price (24 Karat per Ounce)",
                labelFormat: '${value}',
                crosshairTooltip: { enable: true },
                minimum: 1000,
                majorTickLines: { width: 0 },
                lineStyle: { width: 0 }
            }} chartArea={{ border: { width: 0 } }} width={Browser.isDevice ? '100%' : '75%'} title='Historical Gold Prices in USA: 2015 to 2024' tooltip={{ enable: false, shared: false }} crosshair={{ enable: true, snapToData: true, dashArray: '5,5' }} legendSettings={{ visible: false }}>
                        <Inject services={[LineSeries, DateTime, Legend, Crosshair]}/>
                        <SeriesCollectionDirective>
                            <SeriesDirective dataSource={[
                { x: 2015, y: 1160.06 },
                { x: 2016, y: 1250.74 },
                { x: 2017, y: 1257.12 },
                { x: 2018, y: 1268.93 },
                { x: 2019, y: 1393.34 },
                { x: 2020, y: 1770.35 },
                { x: 2021, y: 1798.53 },
                { x: 2022, y: 1800.79 },
                { x: 2023, y: 1923.48 },
                { x: 2024, y: 2003.10 }
            ]} xName='x' yName='y' name='India' type='Line' width={2} marker={{ visible: true, isFilled: true }} animation={{ enable: false }}/>
                        </SeriesCollectionDirective>
                    </ChartComponent>
                </div>
            </div>);
    }
    load(args) {
        let selectedTheme = location.hash.split('/')[1];
        selectedTheme = selectedTheme ? selectedTheme : 'Fluent2';
        args.chart.theme = (selectedTheme.charAt(0).toUpperCase() + selectedTheme.slice(1)).
            replace(/-dark/i, "Dark").replace(/contrast/i, 'Contrast').replace(/-highContrast/i, 'HighContrast');
    }
    ;
}

const root = createRoot(document.getElementById('sample'));
root.render(<CrosshairChart />);

